-- Append-only accounting enforcement below the application layer.
CREATE TRIGGER IF NOT EXISTS "SalesPartnerBillingEvent_No_UPDATE" BEFORE UPDATE ON "SalesPartnerBillingEvent" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesPartnerBillingEvent_No_DELETE" BEFORE DELETE ON "SalesPartnerBillingEvent" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesCommissionEntry_No_UPDATE" BEFORE UPDATE ON "SalesCommissionEntry" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesCommissionEntry_No_DELETE" BEFORE DELETE ON "SalesCommissionEntry" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
