CREATE TRIGGER IF NOT EXISTS "SalesPartnerAdjustment_No_DELETE" BEFORE DELETE ON "SalesPartnerAdjustment" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
