CREATE TRIGGER IF NOT EXISTS "SalesPartnerAuditEvent_No_DELETE" BEFORE DELETE ON "SalesPartnerAuditEvent" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
