CREATE TRIGGER IF NOT EXISTS "SalesPartnerCommissionVersion_No_DELETE" BEFORE DELETE ON "SalesPartnerCommissionVersion" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
