CREATE TRIGGER IF NOT EXISTS "SalesPartnerWebhookReceipt_No_DELETE" BEFORE DELETE ON "SalesPartnerWebhookReceipt" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesSubscriberOwnershipChange_No_UPDATE" BEFORE UPDATE ON "SalesSubscriberOwnershipChange" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesSubscriberOwnershipChange_No_DELETE" BEFORE DELETE ON "SalesSubscriberOwnershipChange" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesRepresentativeAgreement_No_UPDATE" BEFORE UPDATE ON "SalesRepresentativeAgreement" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesRepresentativeAgreement_No_DELETE" BEFORE DELETE ON "SalesRepresentativeAgreement" BEGIN SELECT RAISE(ABORT, 'Append-only history: create a correction instead'); END;
CREATE TRIGGER IF NOT EXISTS "SalesRelationships_OriginalAttribution" BEFORE UPDATE ON "SalesSubscriberRelationship" WHEN OLD.SubscriberUserId!=NEW.SubscriberUserId OR OLD.AcquiringRepresentativeId IS NOT NEW.AcquiringRepresentativeId OR OLD.AcquisitionBillingEventId IS NOT NEW.AcquisitionBillingEventId OR OLD.OriginalCompensationVersionId IS NOT NEW.OriginalCompensationVersionId OR OLD.OriginalPlan!=NEW.OriginalPlan OR OLD.RegisteredAt IS NOT NEW.RegisteredAt OR OLD.AcquiredAt IS NOT NEW.AcquiredAt OR OLD.ResidualEligibleFrom IS NOT NEW.ResidualEligibleFrom BEGIN SELECT RAISE(ABORT,'Original attribution is permanent'); END;
CREATE TRIGGER IF NOT EXISTS "SalesRelationships_No_Delete" BEFORE DELETE ON "SalesSubscriberRelationship" BEGIN SELECT RAISE(ABORT,'Subscriber relationships are permanent'); END;
CREATE TRIGGER IF NOT EXISTS "SalesPayouts_PaidImmutable" BEFORE UPDATE ON "SalesPartnerPayoutBatch" WHEN OLD.State=4 BEGIN SELECT RAISE(ABORT,'Confirmed payout cannot be rewritten'); END;
